1	import type { Metadata } from "next";
2	
3	import CardServer from "@components/ui/card/CardServer";
4	import List from "@components/ui/list";
5	import NoEventsFound from "@components/ui/common/noEventsFound";
6	import HeadingLayout from "@components/ui/hybridEventsList/HeadingLayout";
7	import { buildPageMeta } from "@components/partials/seo-meta";
8	import { siteUrl } from "@config/index";
9	import { fetchEventBySlugWithStatus } from "@lib/api/events";
10	import { captureException } from "@sentry/nextjs";
11	import { filterActiveEvents, isEventActive } from "@utils/event-helpers";
12	import { locale as rootLocale } from "next/root-params";
13	import type { AppLocale } from "types/i18n";
14	import { MAX_FAVORITES } from "@utils/constants";
15	import { getFavoritesFromCookies } from "@utils/favorites";
16	import { getTranslations } from "next-intl/server";
17	import type { EventSummaryResponseDTO } from "types/api/event";
18	import FavoritesAutoPrune from "./FavoritesAutoPrune";
19	import FavoritesPageTracker from "./FavoritesPageTracker";
20	
21	const FETCH_CONCURRENCY = 5;
22	
23	export async function generateMetadata(): Promise<Metadata> {
24	  const locale = (await rootLocale()) as AppLocale;
25	  const t = await getTranslations({ locale, namespace: "App.Favorites" });
26	
27	  return {
28	    ...(buildPageMeta({
29	      title: t("title"),
30	      description: t("description"),
31	      canonical: `${siteUrl}/preferits`,
32	      locale,
33	    }) as Metadata),
34	    robots: "noindex, nofollow",
35	  };
36	}
37	
38	async function fetchFavoritesEvents(
39	  slugs: string[]
40	): Promise<{ events: EventSummaryResponseDTO[]; notFoundSlugs: string[] }> {
41	  const uniqueSlugs = Array.from(new Set(slugs)).slice(0, MAX_FAVORITES);
42	  const results: EventSummaryResponseDTO[] = [];
43	  const notFoundSlugs: string[] = [];
44	
45	  const reasonToString = (reason: unknown): string => {
46	    if (reason instanceof Error) return reason.message;
47	    if (typeof reason === "string") return reason;
48	
49	    try {
50	      return JSON.stringify(reason);
51	    } catch {
52	      return "unknown";
53	    }
54	  };
55	
56	  for (let i = 0; i < uniqueSlugs.length; i += FETCH_CONCURRENCY) {
57	    const chunk = uniqueSlugs.slice(i, i + FETCH_CONCURRENCY);
58	    const fetched = await Promise.allSettled(
59	      chunk.map((slug) => fetchEventBySlugWithStatus(slug))
60	    );
61	
62	    const failedFetches: Array<{ slug: string | undefined; reason: unknown }> =
63	      [];
64	
65	    for (let j = 0; j < fetched.length; j++) {
66	      const slug = chunk[j];
67	      const settled = fetched[j];
68	      if (settled.status !== "fulfilled") {
69	        failedFetches.push({ slug, reason: settled.reason });
70	        continue;
71	      }
72	
73	      const { event, notFound } = settled.value;
74	
75	      if (notFound && slug) {
76	        notFoundSlugs.push(slug);
77	      }
78	
79	      if (event != null) {
80	        results.push(event);
81	      }
82	    }
83	
84	    if (failedFetches.length > 0) {
85	      captureException(new Error("Favorites: fetch failures"), {
86	        tags: {
87	          feature: "favorites",
88	          page: "/preferits",
89	          phase: "fetch_event_by_slug",
90	        },
91	        extra: {
92	          failedCount: failedFetches.length,
93	          failedSlugs: failedFetches.map((f) => f.slug).filter(Boolean),
94	          failedReasons: failedFetches.map((f) => reasonToString(f.reason)),
95	        },
96	      });
97	    }
98	  }
99	
100	  return { events: results, notFoundSlugs };
101	}
102	
103	export default async function PreferitsPage() {
104	  const locale = (await rootLocale()) as AppLocale;
105	  const t = await getTranslations({ locale, namespace: "App.Favorites" });
106	
107	  const favoriteSlugs = [...(await getFavoritesFromCookies())].reverse();
108	  const uniqueFavoritesCount = new Set(favoriteSlugs).size;
109	  const { events, notFoundSlugs } = await fetchFavoritesEvents(favoriteSlugs);
110	  const activeEvents = filterActiveEvents(events);
111	
112	  const expiredSlugs = events.flatMap((event) => {
113	    if (!event.slug) return [];
114	    if (isEventActive(event)) return [];
115	    return [event.slug];
116	  });
117	
118	  const slugsToRemove = Array.from(new Set([...expiredSlugs, ...notFoundSlugs]));
119	
120	  if (favoriteSlugs.length === 0 || activeEvents.length === 0) {
121	    return (
122	      <div className="container py-section-y flex-col justify-center items-center" data-testid="favorites-page-empty">
123	        <FavoritesAutoPrune slugsToRemove={slugsToRemove} />
124	        <FavoritesPageTracker favoritesCount={uniqueFavoritesCount} activeCount={0} />
125	        <NoEventsFound title={t("emptyTitle")} description={t("emptyDescription")} />
126	      </div>
127	    );
128	  }
129	
130	  return (
131	    <div className="container py-section-y flex-col justify-center items-center" data-testid="favorites-page">
132	      <FavoritesAutoPrune slugsToRemove={slugsToRemove} />
133	      <FavoritesPageTracker favoritesCount={uniqueFavoritesCount} activeCount={activeEvents.length} />
134	      <div className="w-full">
135	        <HeadingLayout
136	          title={t("heading")}
137	          subtitle={t("subtitle")}
138	          titleClass="heading-1"
139	          subtitleClass="body-large"
140	          cta={null}
141	        />
142	        <p className="body-small text-foreground/80 mb-element-gap">
143	          {t("countLabel", {
144	            count: uniqueFavoritesCount,
145	            max: MAX_FAVORITES,
146	          })}
147	        </p>
148	      </div>
149	      <List events={activeEvents}>
150	        {(event, index) => (
151	          <CardServer
152	            key={`${event.id}-${index}`}
153	            event={event}
154	            isPriority={index === 0}
155	            initialIsFavorite
156	          />
157	        )}
158	      </List>
159	    </div>
160	  );
161	}
